context:
            "damage_numeric",
            "base_damage",
        ):
            if key in move:
                try:
                    return float(
                        move[key] or 0.0
                    )
                except (
                    TypeError,
                    ValueError,
                ):
                    return 0.0

        return 0.0

    for attribute_name in (
        "damage",
        "damage_numeric",
        "base_damage",
    ):
        value = getattr(
            move,
            attribute_name,
            None,
        )

        if value is not None:
            try:
                return float(value or 0.0)
            except (
                TypeError,
                ValueError,
            ):
                return 0.0

    return 0.0


