class RandomLegalMoveAgent:
    def __init__(
        self,
        seed: int = RANDOM_SEED,
        name: str = "Random Legal Agent",
    ) -> None:
        self.name = name
        self.random = random.Random(
            seed
        )
        self.last_decision = None

    def choose_move(
        self,
        state: Any = None,
        depth: int | None = None,
        battle_state: Any = None,
        **kwargs: Any,
    ) -> TournamentDecision:
        resolved_state = (
            state
            if state is not None
            else battle_state
        )

        if resolved_state is None:
            raise ValueError(
                "A battle state is required."
            )

        legal_moves = (
            get_current_legal_moves(
                resolved_state
            )
        )

        if not legal_moves:
            self.last_decision = (
                TournamentDecision(
                    move=None,
                    score=0.0,
                    search_depth=int(
                        depth or 0
                    ),
                    nodes=0,
                    confidence=0.0,
                    selected_move_name=None,
                    fallback=True,
                    reason=
                        "No legal moves available.",
                )
            )

            return self.last_decision

        selected_move = (
            self.random.choice(
                legal_moves
            )
        )

        confidence = (
            1.0
            / len(legal_moves)
        )

        self.last_decision = (
            TournamentDecision(
                move=
                    selected_move,

                score=
                    confidence,

                search_depth=int(
                    depth or 0
                ),

)

